name: Notify dev channel

on:
  push:
    branches: [master]
    paths:
      - 'src/**'

jobs:
  notify:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Get merge commit message
        id: merge_msg
        run: |
          echo "commit_msg=$(git log -1 --pretty=%B)" >> $GITHUB_OUTPUT

      - name: Extract PR number
        id: pr_number
        run: |
          echo "pr_number=$(echo '${{ steps.merge_msg.outputs.commit_msg }}' | grep -oP 'Merge pull request #\K[0-9]+')" >> $GITHUB_OUTPUT

      - name: Get PR body
        id: pr_body
        uses: actions/github-script@v6
        env:
          PR_NUMBER: ${{ steps.pr_number.outputs.pr_number }}
        with:
          script: |
            const prNumber = parseInt(process.env.PR_NUMBER, 10);
            if (!prNumber) {
              core.setFailed('No PR number found');
              return;
            }
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });
            core.setOutput('body', pr.body || '');
            core.setOutput('title', pr.title || '');
            core.setOutput('html_url', pr.html_url || '');

      - name: Find linked issues
        id: linked_issues
        run: |
          body="${{ steps.pr_body.outputs.body }}"
          echo "body=$body" >> $GITHUB_OUTPUT
          issues=$(echo "$body" | grep -oP '(?i)(Closes|Fixes|Resolves)\s+#\K[0-9]+' | tr '\n' ',')
          echo "issues=$issues" >> $GITHUB_OUTPUT

      - name: Post comment to PR
        if: steps.pr_number.outputs.pr_number != ''
        uses: actions/github-script@v6
        env:
          PR_NUMBER: ${{ steps.pr_number.outputs.pr_number }}
        with:
          script: |
            const prNumber = parseInt(process.env.PR_NUMBER, 10);
            const comment = `## 🧪 Your changes are now in the dev channel!\n\nYour PR has been merged to master and is available for testing in the **dev channel**.\n\n**Test your changes before the Tuesday release:**\n📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**\n\nQuick start: \`uvx ha-mcp-dev\``;
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: comment
            });

      - name: Post comment to linked issues
        if: steps.linked_issues.outputs.issues != ''
        uses: actions/github-script@v6
        env:
          PR_NUMBER: ${{ steps.pr_number.outputs.pr_number }}
        with:
          script: |
            const issueNumbers = '${{ steps.linked_issues.outputs.issues }}'.split(',').filter(Boolean);
            const prNumber = parseInt(process.env.PR_NUMBER, 10);
            const comment = `## ✅ This issue has been addressed in the dev channel!\n\nA fix for this issue has been merged to master (PR #${prNumber}) and is available for testing...`;
            for (const issueNumber of issueNumbers) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: parseInt(issueNumber, 10),
                body: comment
              });
            }
